    return self._datetime.fold"}, {"qualname": "arrow/arrow.py::Arrow.dehumanize", "source": "def dehumanize(self, timestring: str, locale: str = "en_us") -> "Arrow":
    locale_obj = locales.get_locale(locale)
    normalized_locale_name = locale.lower().replace("_", "-")
    if normalized_locale_name not in DEHUMANIZE_LOCALES:
        raise ValueError(f"Dehumanize does not currently support the {locale} locale, please consider making a contribution to add support for this locale.")
    current_time = self.fromdatetime(self._datetime)
    time_object_info = dict.fromkeys(["seconds", "minutes", "hours", "days", "weeks", "months", "years"], 0)
    unit_visited = dict.fromkeys(["now", "seconds", "minutes", "hours", "days", "weeks", "months", "years"], False)
    num_pattern = re.compile(r"\d+")
    for unit in locale_obj.timeframes:
        change_value = 0
        search_string = str(locale_obj.timeframes[unit]).format(r"\d+")
        pattern = re.compile(fr"{search_string}")
        match = pattern.search(timestring)
        if not match:
            continue
        match_string = match.group()
        num_match = num_pattern.search(match_string)
        change_value = int(num_match.group()) if num_match else 1
        if unit == "now":
            unit_visited[unit] = True
            continue
        time_unit_to_change = str(unit) + ("s" if str(unit)[-1] != "s" else "")
        time_object_info[time_unit_to_change] = change_value
        unit_visited[time_unit_to_change] = True
    if not any(unit_visited.values()):
        raise ValueError("Input string not valid. Note: Some locales do not support the week granulairty in Arrow. If you are attempting to use the week granularity on an unsupported locale, this could be the cause of this error.")
    future_string = locale_obj.future.format(".*")
    future_pattern = re.compile(fr"^{future_string}$")
    future_pattern_match = future_pattern.findall(timestring)
    past_string = locale_obj.past.format(".*")
    past_pattern = re.compile(fr"^{past_string}$")
    past_pattern_match = past_pattern.findall(timestring)
    if past_pattern_match:
        sign_val = -1
    elif future_pattern_match:
        sign_val = 1
    elif unit_visited["now"]:
        sign_val = 0
    else:
        raise ValueError("Invalid input String. String does not contain any relative time information. String should either represent a time in the future or a time in the past. Ex: 'in 5 seconds' or '5 seconds ago'.")
    time_changes = {k: sign_val * v for k, v in time_object_info.items()}
    return current_time.shift(**time_changes)"}, {"qualname": "arrow/locales.py::Locale.describe", "source": "def describe(self, timeframe: TimeFrameLiteral, delta: Union[float, int] = 0, only_distance: bool = False) -> str:
