    return self.timeframes[key].format(abs(delta))"}, {"qualname": "arrow/locales.py::HebrewLocale.describe_multi", "source": "def describe_multi(self, timeframes: Sequence[Tuple[TimeFrameLiteral, Union[int, float]]], only_distance: bool = False) -> str:
    humanized = ""
    for i, (tf, d) in enumerate(timeframes):
        last_humanized = self._format_timeframe(tf, trunc(d))
        if i == 0:
            humanized = last_humanized
        elif i == len(timeframes) - 1:
            humanized += " " + self.and_word
            humanized += "be" if last_humanized[0].isdecimal() else ""
            humanized += last_humanized
